import{_ as d,o as e,c as o,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"API 参考","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/api.md","filePath":"advanced/api.md","lastUpdated":1790783629000}'),r={name:"advanced/api.md"};function c(i,t,h,s,l,n){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h1><blockquote><p>本页为开发者参考。除特别标注外，接口均返回 JSON <code>{ success: true, ... }</code>，管理接口需 <code>admin</code>/<code>root</code> 角色。</p></blockquote><hr><h2 id="请求与响应的通用规则" tabindex="-1">请求与响应的通用规则 <a class="header-anchor" href="#请求与响应的通用规则" aria-label="Permalink to &quot;请求与响应的通用规则&quot;">​</a></h2><p>调用任何接口之前，先了解鉴权走哪条通道、响应长什么样、流式数据怎么读，以及有哪些限流。</p><h3 id="鉴权三通道" tabindex="-1">鉴权三通道 <a class="header-anchor" href="#鉴权三通道" aria-label="Permalink to &quot;鉴权三通道&quot;">​</a></h3><p><code>extractAccessToken</code> 按 <strong>query <code>token</code> → cookie <code>access_token</code> → <code>Authorization: Bearer</code></strong> 的顺序取 token，原理见<a href="/advanced/auth">鉴权模型</a>。不同调用方式该选哪条通道如下：</p><ul><li><p>浏览器 REST：请求带 <code>credentials: &#39;include&#39;</code>。HTTPS 下走 httpOnly cookie（JavaScript 读不到的 Cookie），HTTP 下走本地缓存的 Bearer。这部分前端 <code>apiFetch</code> 已经封装好，无需额外处理。</p></li><li><p>媒体地址（<code>&lt;video&gt;</code> / <code>&lt;audio&gt;</code> / MSE / hls.js）：无法带自定义头，前端对本域 <code>/api/</code> URL 自动附加 <code>?token=</code>。</p></li><li><p>脚本/第三方调用：可用 <code>Authorization: Bearer &lt;access&gt;</code>，过期后 <code>POST /api/auth/refresh</code>（cookie 或 body）换发 access。</p></li></ul><h3 id="响应与流式" tabindex="-1">响应与流式 <a class="header-anchor" href="#响应与流式" aria-label="Permalink to &quot;响应与流式&quot;">​</a></h3><p>所有接口共用同一套响应外壳，流式接口另有约定。</p><ul><li><p>成功返回 <code>{ &quot;success&quot;: true, &quot;data&quot;: { ... } }</code>；错误返回 <code>{ &quot;success&quot;: false, &quot;error&quot;: { &quot;message&quot;: &quot;...&quot;, &quot;code&quot;: &quot;ERROR_CODE&quot; } }</code>。</p></li><li><p>流式接口（B站视频解析、B站下载、server-files 上传进度）返回 <strong>NDJSON</strong>（<code>application/x-ndjson</code>）。NDJSON 是每行一个独立 JSON 对象的格式，客户端需要逐行解析：</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;status&quot;:&quot;parsing&quot;,&quot;step&quot;:&quot;playurl&quot;,&quot;message&quot;:&quot;获取播放地址...&quot;}</span></span>\n<span class="line"><span>{&quot;success&quot;:true,&quot;status&quot;:&quot;done&quot;,&quot;videoUrl&quot;:&quot;...&quot;,&quot;format&quot;:&quot;dash&quot;,&quot;currentQn&quot;:80}</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;status&quot;:&quot;downloading&quot;,&quot;phase&quot;:&quot;video&quot;,&quot;received&quot;:123456,&quot;total&quot;:987654,&quot;percent&quot;:12}</span></span>\n<span class="line"><span>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;解析失败&quot;,&quot;code&quot;:&quot;NO_PERMISSION&quot;}</span></span></code></pre></div><h3 id="限流" tabindex="-1">限流 <a class="header-anchor" href="#限流" aria-label="Permalink to &quot;限流&quot;">​</a></h3><p>限流规则按接口类型区分，具体数值与后端保持一致。登录为 15 分钟 20 次/IP；改密为 1 分钟 3 次/用户；登录失败锁定默认关闭，开启后 5 次锁 15 分钟。代理类接口需登录，防止带宽滥用。</p><hr><h2 id="认证-api-auth" tabindex="-1">认证 <code>/api/auth</code> <a class="header-anchor" href="#认证-api-auth" aria-label="Permalink to &quot;认证 `/api/auth`&quot;">​</a></h2><p>账号、令牌和登录态相关的接口都挂在 <code>/api/auth</code> 下。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>POST</td><td><code>/register</code></td><td>注册新用户（approval 模式下为 pending）</td><td>开放</td></tr><tr><td>POST</td><td><code>/login</code></td><td>登录，HTTPS 下写 httpOnly Cookie</td><td>开放</td></tr><tr><td>POST</td><td><code>/refresh</code></td><td>刷新 Access Token（不轮换 refresh）</td><td>登录</td></tr><tr><td>POST</td><td><code>/logout</code></td><td>登出</td><td>登录</td></tr><tr><td>GET</td><td><code>/registration-mode</code></td><td>当前注册模式</td><td>开放</td></tr><tr><td>GET</td><td><code>/public-settings</code></td><td>公开设置（注册模式、建房模式、功能开关、权限矩阵）</td><td>开放</td></tr><tr><td>GET</td><td><code>/me</code></td><td>当前用户信息</td><td>登录</td></tr><tr><td>PATCH</td><td><code>/password</code></td><td>修改密码（触发 token 全局吊销）</td><td>登录</td></tr><tr><td>PATCH</td><td><code>/username</code></td><td>修改用户名</td><td>root</td></tr><tr><td>POST</td><td><code>/avatar</code></td><td>上传头像</td><td>登录</td></tr><tr><td>DELETE</td><td><code>/avatar</code></td><td>删除头像</td><td>登录</td></tr><tr><td>POST</td><td><code>/guest</code></td><td>获取游客令牌（userId=0）</td><td>开放</td></tr></tbody></table><h2 id="房间-api-rooms" tabindex="-1">房间 <code>/api/rooms</code> <a class="header-anchor" href="#房间-api-rooms" aria-label="Permalink to &quot;房间 `/api/rooms`&quot;">​</a></h2><p>房间列表和影片的增删改查都在 <code>/api/rooms</code> 下。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/</code></td><td>活跃房间列表</td><td>登录</td></tr><tr><td>PUT</td><td><code>/:roomId/name</code></td><td>修改房间名称</td><td>房主/root</td></tr><tr><td>GET</td><td><code>/:roomId/movies</code></td><td>影片列表</td><td>房间成员</td></tr><tr><td>POST</td><td><code>/:roomId/movies</code></td><td>新增影片</td><td>房主</td></tr><tr><td>POST</td><td><code>/:roomId/movies/reorder</code></td><td>重排序</td><td>房主</td></tr><tr><td>PUT</td><td><code>/:roomId/movies/:movieId</code></td><td>更新影片</td><td>房主</td></tr><tr><td>DELETE</td><td><code>/:roomId/movies/:movieId</code></td><td>删除影片</td><td>房主</td></tr></tbody></table><h2 id="流媒体-api-stream" tabindex="-1">流媒体 <code>/api/stream</code> <a class="header-anchor" href="#流媒体-api-stream" aria-label="Permalink to &quot;流媒体 `/api/stream`&quot;">​</a></h2><p><code>/api/stream</code> 集中了播放相关的接口，按内容来源分成 B站、弹幕、番剧源三组。</p><h3 id="b站相关" tabindex="-1">B站相关 <a class="header-anchor" href="#b站相关" aria-label="Permalink to &quot;B站相关&quot;">​</a></h3><p>登录、解析和代理播放的接口如下，其中解析接口以 NDJSON 流式返回。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/proxy-image</code></td><td>B站图片代理（免认证，1 小时缓存）</td><td>开放</td></tr><tr><td>GET</td><td><code>/bilibili/qr</code></td><td>扫码登录二维码</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/qr/poll</code></td><td>轮询扫码状态</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/login-status</code></td><td>登录状态</td><td>登录</td></tr><tr><td>POST</td><td><code>/bilibili/logout</code></td><td>登出</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/user-info</code></td><td>用户信息（含会员状态）</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/following-bangumi</code></td><td>关注的番剧</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/bangumi-episodes</code></td><td>番剧集数</td><td>登录</td></tr><tr><td>GET</td><td><code>/resolve-bilibili</code></td><td>视频解析（NDJSON 流式）</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/danmaku</code></td><td>B站弹幕（cid 或 bvid）</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/ai-subtitle</code></td><td>AI 字幕（须带 <code>duration</code> 做带内校验）</td><td>登录</td></tr><tr><td>GET</td><td><code>/bilibili/related</code></td><td>相关推荐（自动连播使用）</td><td>登录</td></tr><tr><td>GET</td><td><code>/proxy</code></td><td>CDN 媒体代理（域名白名单 + 防盗链头）</td><td>登录</td></tr></tbody></table><h3 id="弹幕-api-stream-danmaku" tabindex="-1">弹幕 <code>/api/stream/danmaku</code> <a class="header-anchor" href="#弹幕-api-stream-danmaku" aria-label="Permalink to &quot;弹幕 `/api/stream/danmaku`&quot;">​</a></h3><p>弹幕接口可以对接多个弹幕源，搜索时对繁简变体并行处理。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/sources</code></td><td>弹幕源列表（B站 / 巴哈姆特 / 弹弹play）</td><td>登录</td></tr><tr><td>GET</td><td><code>/search</code></td><td>搜索弹幕（繁简变体并行）</td><td>登录</td></tr><tr><td>GET</td><td><code>/episodes</code></td><td>剧集列表</td><td>登录</td></tr><tr><td>POST</td><td><code>/fetch</code></td><td>拉取弹幕（<code>playbackParams</code> 须原样回传）</td><td>登录</td></tr></tbody></table><h3 id="番剧源" tabindex="-1">番剧源 <a class="header-anchor" href="#番剧源" aria-label="Permalink to &quot;番剧源&quot;">​</a></h3><p><code>/anime</code>、<code>/anisubs</code>、<code>/kazumi</code> 三组结构一致：</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/proxy</code></td><td>媒体代理</td><td>登录</td></tr><tr><td>GET</td><td><code>/sources</code></td><td>数据源列表</td><td>登录</td></tr><tr><td>GET</td><td><code>/search</code></td><td>搜索番剧</td><td>登录</td></tr><tr><td>GET</td><td><code>/episodes</code></td><td>剧集列表</td><td>登录</td></tr><tr><td>POST</td><td><code>/resolve</code></td><td>解析播放地址</td><td>登录</td></tr></tbody></table><h2 id="挂载点-api-webdav、-api-ftp、-api-openlist、-api-emby、-api-jellyfin" tabindex="-1">挂载点 <code>/api/webdav</code>、<code>/api/ftp</code>、<code>/api/openlist</code>、<code>/api/emby</code>、<code>/api/jellyfin</code> <a class="header-anchor" href="#挂载点-api-webdav、-api-ftp、-api-openlist、-api-emby、-api-jellyfin" aria-label="Permalink to &quot;挂载点 `/api/webdav`、`/api/ftp`、`/api/openlist`、`/api/emby`、`/api/jellyfin`&quot;">​</a></h2><p>五类挂载点共用同一组接口，路径分别挂在各自的前缀下。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/mounts</code></td><td>挂载点列表</td><td>登录</td></tr><tr><td>POST</td><td><code>/mounts/test</code></td><td>测试连接（直链模式同步做 https 活性探测）</td><td>登录</td></tr><tr><td>POST</td><td><code>/mounts</code></td><td>新增挂载点</td><td>登录</td></tr><tr><td>PUT</td><td><code>/mounts/:id</code></td><td>更新挂载点</td><td>登录</td></tr><tr><td>DELETE</td><td><code>/mounts/:id</code></td><td>删除挂载点</td><td>登录</td></tr><tr><td>GET</td><td><code>/mounts/:id/browse</code></td><td>浏览目录</td><td>登录</td></tr><tr><td>GET</td><td><code>/resolve</code></td><td>解析文件（直链或代理 URL）</td><td>登录</td></tr><tr><td>GET</td><td><code>/proxy</code></td><td>代理播放</td><td>登录</td></tr><tr><td>GET</td><td><code>/embedded-tracks</code></td><td>内嵌字幕轨列表（emby/jellyfin）</td><td>登录</td></tr><tr><td>GET</td><td><code>/embedded-extract</code></td><td>内嵌字幕提取（emby/jellyfin）</td><td>登录</td></tr></tbody></table><ul><li>ftp 无直链模式，<code>/resolve</code> 恒返回代理 URL。</li><li>emby/jellyfin 音轨不兼容时自动切服务端转码 HLS（代理超时放宽到 90s）。</li></ul><h2 id="直链实时解析-api-direct-resolve" tabindex="-1">直链实时解析 <code>/api/direct-resolve</code> <a class="header-anchor" href="#直链实时解析-api-direct-resolve" aria-label="Permalink to &quot;直链实时解析 `/api/direct-resolve`&quot;">​</a></h2><p>播放时需要一个仍然有效的直链，这个接口负责现取。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/movie?movieId=</code></td><td>播放时取新鲜直链（5 分钟 TTL + 单飞去重 + https 活性自愈）</td><td>登录</td></tr></tbody></table><h2 id="字幕-api-subtitles" tabindex="-1">字幕 <code>/api/subtitles</code> <a class="header-anchor" href="#字幕-api-subtitles" aria-label="Permalink to &quot;字幕 `/api/subtitles`&quot;">​</a></h2><p>字幕接口负责在同目录下找字幕、浏览字幕目录，以及读取字幕内容。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/search?movieId=</code></td><td>同目录同名前缀字幕（webdav/openlist/ftp/server-files）</td><td>登录</td></tr><tr><td>GET</td><td><code>/browse</code></td><td>浏览字幕目录</td><td>登录</td></tr><tr><td>GET</td><td><code>/load?movieId=&amp;path=</code></td><td>加载字幕内容（非 URL，上限 2MB）</td><td>登录</td></tr></tbody></table><h2 id="一起听音乐-api-music" tabindex="-1">一起听音乐 <code>/api/music</code> <a class="header-anchor" href="#一起听音乐-api-music" aria-label="Permalink to &quot;一起听音乐 `/api/music`&quot;">​</a></h2><p>音乐模块的接口覆盖网易云转发、音频流、音质查询和云盘上传。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET/POST</td><td><code>/ncm/*</code></td><td>网易云接口通用转发（注入用户 Cookie）</td><td>可选鉴权</td></tr><tr><td>GET</td><td><code>/stream?songId=&amp;level=&amp;roomId=&amp;direct=</code></td><td>音频流（降级链 + 凭证回退 + SSRF 防护）</td><td>可选鉴权</td></tr><tr><td>GET</td><td><code>/song-quality?songId=</code></td><td>音质元数据（15 分钟缓存）</td><td>登录</td></tr><tr><td>GET</td><td><code>/login/status</code></td><td>网易云登录态（含会员判定）</td><td>登录</td></tr><tr><td>GET</td><td><code>/ncm-cookie</code></td><td>返回当前用户的网易云 Cookie 串（个人中心「复制 Cookie」）</td><td>登录</td></tr><tr><td>POST</td><td><code>/ncm-cookie-login</code></td><td>粘贴 Cookie 登录（提交时校验 MUSIC_U 登录态）</td><td>登录</td></tr><tr><td>POST</td><td><code>/logout</code></td><td>清除网易云凭证</td><td>登录</td></tr><tr><td>POST</td><td><code>/cloud/upload</code></td><td>云盘上传（流式转发）</td><td>登录</td></tr></tbody></table><h2 id="cli-代理-api-cli" tabindex="-1">CLI 代理 <code>/api/cli</code> <a class="header-anchor" href="#cli-代理-api-cli" aria-label="Permalink to &quot;CLI 代理 `/api/cli`&quot;">​</a></h2><p>服务端为 CLI 保留了一个解析入口，供本机代理做高画质解析时使用。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/resolve</code></td><td>用请求头自带 Cookie 解析（供 CLI 高画质）</td><td>登录</td></tr></tbody></table><h2 id="服务器文件-api-server-files-仅-root" tabindex="-1">服务器文件 <code>/api/server-files</code>（仅 root） <a class="header-anchor" href="#服务器文件-api-server-files-仅-root" aria-label="Permalink to &quot;服务器文件 `/api/server-files`（仅 root）&quot;">​</a></h2><p>这组接口管理服务器本机上的目录与文件，只对 root 开放。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/roots</code></td><td>根目录列表</td></tr><tr><td>POST</td><td><code>/roots</code></td><td>添加根目录</td></tr><tr><td>DELETE</td><td><code>/roots/:id</code></td><td>删除根目录</td></tr><tr><td>GET</td><td><code>/browse</code></td><td>浏览目录</td></tr><tr><td>GET</td><td><code>/browse-system</code></td><td>浏览全盘</td></tr><tr><td>POST</td><td><code>/upload</code></td><td>上传文件（上限 10GB）</td></tr><tr><td>POST</td><td><code>/folder</code></td><td>新建文件夹</td></tr><tr><td>POST</td><td><code>/rename</code></td><td>重命名</td></tr><tr><td>DELETE</td><td><code>/file</code></td><td>删除文件/文件夹</td></tr><tr><td>GET</td><td><code>/resolve</code></td><td>解析播放 URL</td></tr><tr><td>GET</td><td><code>/proxy</code></td><td>代理播放（1MB 读块）</td></tr><tr><td>POST</td><td><code>/bilibili-download</code></td><td>B站下载（仅 MP4 最高 720P，NDJSON 进度）</td></tr></tbody></table><h2 id="管理后台-api-admin" tabindex="-1">管理后台 <code>/api/admin</code> <a class="header-anchor" href="#管理后台-api-admin" aria-label="Permalink to &quot;管理后台 `/api/admin`&quot;">​</a></h2><p><code>/api/admin</code> 下的接口按用途分成用户管理、房间管理、系统设置三组。</p><h3 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h3><p>用户管理负责审核注册、调整角色和删除账号，权限要求最高的几项只对 root 开放。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/users</code></td><td>用户列表</td><td>admin/root</td></tr><tr><td>PATCH</td><td><code>/users/:id/role</code></td><td>修改角色（仅 admin/user，root 不可改）</td><td>root</td></tr><tr><td>POST</td><td><code>/users/:id/approve</code></td><td>审核注册</td><td>root</td></tr><tr><td>DELETE</td><td><code>/users/:id</code></td><td>删除用户（触发 token 吊销）</td><td>root</td></tr></tbody></table><h3 id="房间管理" tabindex="-1">房间管理 <a class="header-anchor" href="#房间管理" aria-label="Permalink to &quot;房间管理&quot;">​</a></h3><p>房间管理可以查看全量房间，也可以强制关闭或批量清理房间。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/rooms</code></td><td>全量房间列表</td><td>admin/root</td></tr><tr><td>DELETE</td><td><code>/rooms/:roomId</code></td><td>强制关闭房间（先广播再断连）</td><td>admin/root</td></tr><tr><td>POST</td><td><code>/rooms/batch-delete</code></td><td>批量删除</td><td>root</td></tr><tr><td>POST</td><td><code>/rooms/delete-all</code></td><td>清空所有房间</td><td>root</td></tr><tr><td>POST</td><td><code>/rooms/cleanup-unused</code></td><td>清理无人房间</td><td>admin/root</td></tr></tbody></table><h3 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h3><p>系统设置接口读取和写入全局配置，写入只允许 root 执行。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/settings</code></td><td>获取设置（注册模式、建房模式、权限矩阵、功能开关、自动清理）</td><td>admin/root</td></tr><tr><td>PUT</td><td><code>/settings</code></td><td>更新设置</td><td>root</td></tr></tbody></table><h2 id="系统更新-api-system-update-仅-root" tabindex="-1">系统更新 <code>/api/system/update</code>（仅 root） <a class="header-anchor" href="#系统更新-api-system-update-仅-root" aria-label="Permalink to &quot;系统更新 `/api/system/update`（仅 root）&quot;">​</a></h2><p>系统更新接口负责检查新版本、下载并应用更新，也支持上传压缩包。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/check</code></td><td>检查更新（可关预发布接收）</td></tr><tr><td>POST</td><td><code>/apply</code></td><td>下载并应用更新（进度流式）</td></tr><tr><td>POST</td><td><code>/upload</code></td><td>上传压缩包更新</td></tr></tbody></table><h2 id="其他接口" tabindex="-1">其他接口 <a class="header-anchor" href="#其他接口" aria-label="Permalink to &quot;其他接口&quot;">​</a></h2><p>剩下的接口用于推流配置、前端日志上报和健康检查。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/stream-push/obs-config/:roomId</code></td><td>下载 OBS 场景配置</td><td>房主</td></tr><tr><td>POST</td><td><code>/api/client-logs</code></td><td>上报前端日志</td><td>开放</td></tr><tr><td>GET</td><td><code>/health</code></td><td>健康检查</td><td>开放</td></tr></tbody></table><hr><h2 id="错误码汇总" tabindex="-1">错误码汇总 <a class="header-anchor" href="#错误码汇总" aria-label="Permalink to &quot;错误码汇总&quot;">​</a></h2><p>接口返回的错误码含义如下表。</p><table tabindex="0"><thead><tr><th>code</th><th>HTTP</th><th>含义</th></tr></thead><tbody><tr><td><code>NCM_UNAVAILABLE</code></td><td>503</td><td>内嵌网易云服务未启动</td></tr><tr><td><code>VIP_REQUIRED</code></td><td>403</td><td>音质/清晰度需 VIP（含 B站下载会员档强校验）</td></tr><tr><td><code>NO_COPYRIGHT</code></td><td>404</td><td>无版权（<code>/check/music</code> 判定）</td></tr><tr><td><code>RESOLVE_FAILED</code></td><td>502</td><td>地址解析全链失败</td></tr><tr><td><code>UPSTREAM_ERROR</code></td><td>502</td><td>上游返回非预期内容</td></tr><tr><td><code>NOT_FOUND</code> / <code>AUTH_FAILED</code></td><td>404 / 401</td><td>挂载点或文件缺失 / 凭证失效（直链解析）</td></tr><tr><td><code>INTERNAL_NETWORK_FORBIDDEN</code></td><td>400</td><td>拒绝解析内网地址（SSRF 防护）</td></tr><tr><td><code>ALREADY_IN_ROOM</code></td><td>—</td><td>重复加入房间（socket ack）</td></tr><tr><td><code>RESOLVE_FAILED</code> / <code>NO_PERMISSION</code> / <code>CDN_UNREACHABLE</code> / <code>DASH_NOT_AVAILABLE</code> 等</td><td>—</td><td>B站解析 NDJSON 错误行</td></tr></tbody></table><h2 id="socket-io-事件" tabindex="-1">Socket.IO 事件 <a class="header-anchor" href="#socket-io-事件" aria-label="Permalink to &quot;Socket.IO 事件&quot;">​</a></h2><p>房间同步、音乐、投屏信令等实时能力不走 REST，事件清单见<a href="/advanced/sync">房间同步逻辑</a>与<a href="/advanced/music-pipeline">一起听音乐管线</a>。REST 与 WebSocket 共用同一套 JWT 身份。</p>',75)])])}const b=d(r,[["render",c]]);export{u as __pageData,b as default};
